// Non-extractable HMAC key kept in IndexedDB: scripts can use it to sign but can never read or copy it.
const idb = () => new Promise((res, rej) => { const r = indexedDB.open('oranget', 1); r.onupgradeneeded = () => r.result.createObjectStore('k'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error) })
