// Salted PBKDF2 password hashing (passwords are never stored).
async function hashPass(pass, salt = crypto.getRandomValues(new Uint8Array(16))) {
  const base = await subtle().importKey('raw', enc.encode(pass), 'PBKDF2', false, ['deriveBits'])
  const bits = await subtle().deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: 150000 }, base, 256)
  return { salt: b64(salt), hash: b64(bits) }
}

