function AuthModal({ mode, onClose, onDone }) {
  const [m, setM] = useState(mode), [name, setName] = useState(''), [pass, setPass] = useState(''), [err, setErr] = useState(''), [busy, setBusy] = useState(false)
  const submit = async (e) => {
    e.preventDefault(); if (busy) return
    setBusy(true); setErr('')
    try { onDone(m === 'signup' ? await signUp(name, pass) : await logIn(name, pass)) } catch (x) { setErr(x.message); setBusy(false) }
  }
  return (
    <div className="fixed inset-0 z-20 grid place-items-center bg-black/50 p-4" onClick={onClose}>
      <form onSubmit={submit} onClick={(e) => e.stopPropagation()} className="w-full max-w-sm space-y-3 rounded-[2rem] bg-[#fba852] p-6 text-white shadow-2xl border-b-8 border-black/25">
        <h2 className="chunk text-3xl">{m === 'signup' ? 'Create account' : 'Welcome back'}</h2>
        <input className={FIELD} placeholder="Username" autoComplete="username" value={name} onChange={(e) => setName(e.target.value)} autoFocus />
        <input className={FIELD} type="password" placeholder="Password" autoComplete={m === 'signup' ? 'new-password' : 'current-password'} value={pass} onChange={(e) => setPass(e.target.value)} />
        {err && <p className="text-[#8a1c00]" role="alert">{err}</p>}
        <button disabled={busy} className="btn w-full bg-[#fff4d6] text-[#5a2608] text-lg disabled:opacity-60">{busy ? 'One moment…' : m === 'signup' ? 'Sign Up' : 'Log In'}</button>
        <p className="mute text-center text-xs">Your progress saves to the cloud, so you can log in from any browser.</p>
        <button type="button" className="w-full text-sm underline" onClick={() => { setErr(''); setM(m === 'signup' ? 'login' : 'signup') }}>
          {m === 'signup' ? 'Have an account? Log in' : 'New here? Sign up'}
        </button>
      </form>
    </div>
  )
}

function Landing({ onAuth }) {
  const [modal, setModal] = useState(() => { const p = (location.pathname.split('/').pop() || '').toLowerCase(); return p === 'login.html' ? 'login' : p === 'register.html' ? 'signup' : null })
  const fan = [{ id: 'rocket', r: -9, x: -125, y: 36 }, { id: 'plate', r: 9, x: 125, y: 36 }, { id: 'z_blackdragon', r: 0, x: 0, y: -4, big: 1 }]
  return (
    <div className="app-bg relative min-h-screen overflow-hidden"><FallingBlooks />
      <header className="relative z-10 flex items-center justify-between p-5 sm:px-10"><div className="logo">Oranget</div>
        <div className="flex gap-2"><button className="btn bg-white/60" onClick={() => setModal('login')}>Log in</button><button className="btn bg-[#fff4d6]" onClick={() => setModal('signup')}>Sign up</button></div></header>
      <main className="relative z-10 mx-auto grid max-w-6xl items-center gap-10 px-6 pb-16 pt-6 sm:px-10 lg:grid-cols-2">
        <div>
          <h1 className="chunk hero-title text-6xl sm:text-8xl">Oranget</h1>
          <p className="mute mt-1">pronounced orange-it</p>
          <p className="mt-6 max-w-md text-xl leading-snug">Open packs, collect rare blooks, trade live with other players and climb the leaderboard.</p>
          <button className="btn mt-8 bg-[#fff4d6] text-lg" onClick={() => setModal('signup')}>Get started</button>
        </div>
        <div className="relative mx-auto h-[26rem] w-full max-w-md" aria-hidden="true">
          {fan.map((c) => { const b = byId(c.id); return (
            <div key={c.id} className="lcard" style={{ '--c': RARITY[b.rarity].color, zIndex: c.big ? 2 : 1, transform: `translate(${c.x}px,${c.y}px) rotate(${c.r}deg) scale(${c.big ? 1.12 : 1})` }}>
              <div className="mx-auto grid place-items-center"><Blook id={c.id} size={c.big ? 150 : 110} /></div>
              <div className="chunk mt-2">{b.name}</div><div className="text-sm" style={{ color: RARITY[b.rarity].color }}>{RARITY[b.rarity].label}</div></div>) })}
        </div>
      </main>
      {modal && <AuthModal mode={modal} onClose={() => setModal(null)} onDone={(u) => onAuth(u)} />}
    </div>
  )
}

