      snap.docChanges().forEach((c) => { if (c.type !== 'added' || ids.has(c.doc.id)) return; ids.add(c.doc.id); const d = c.doc.data({ serverTimestamps: 'estimate' }); try { add(JSON.parse(d.m), c.doc.id, ms(d.ts)) } catch {} })
